def block(lang,doc):
 title,summ,secs=doc
 date=DATE_RU if lang=='ru' else DATE_KK
 s=f'<div data-lang="{lang}"{" hidden" if lang=="kk" else ""}><h1>{title}</h1><p class="meta">{date}</p>'
 s+=f'<div class="summary"><h2>{summ[0].replace("<b>","").replace("</b>","")}</h2><ul>'+''.join(f'<li>{x}</li>' for x in summ[1:])+'</ul></div>'
 for h,body in secs:s+=f'<section><h2>{h}</h2>{body}</section>'
 return s+'</div>'

